#include <iostream>
#include <vector>
using namespace std;

int main() {   //@ @layout open:container
    vector<vector<int>> grid(3, vector<int>(3, 0));   //@ @tts [next] 準備一張三乘三的地圖，全部是空地 @layout maze:grid
    grid[1][1] = 1;   //@ @guide {grid} {grid[1][1]:orange} @tts [next] 在正中間築一道牆
    grid[0][2] = 1;   //@ @guide {grid} {grid[0][2]:orange} @tts [next] 右上角也築一道牆
    grid[2][0] = 2;   //@ @guide {grid} {grid[2][0]:lime} @tts [next] 左下角標成二，當作終點
    cout << grid[1][1] << endl;   //@ @guide {grid} @tts [next] 地圖完成了
    return 0;   //@ @tts [continue] 程式結束
}
